BEGIN;
-- F44 independently binds new automation/history/review records to their checked source.
-- No prior applied migration or retained financial row is rewritten.
CREATE FUNCTION encova_finance_automation_insert_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE s public."FinanceRecurringSchedule"%ROWTYPE;r public."FinanceRecurringRun"%ROWTYPE;BEGIN
 IF TG_TABLE_NAME='FinanceRecurringSchedule' THEN
  IF NOT public.encova_finance_automation_access(NEW."createdById",NEW."grantId") OR NEW.version<>1 OR NOT NEW.active THEN RAISE EXCEPTION 'FINANCE_OWNER_REQUIRED' USING ERRCODE='P0001';END IF;
  IF (NEW."startMonth"||'-01')::date<DATE '0001-01-01' OR NEW."endMonth" IS NOT NULL AND(NEW."endMonth"||'-01')::date<DATE '0001-01-01' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 ELSIF TG_TABLE_NAME='FinanceRecurringRun' THEN
  SELECT * INTO s FROM public."FinanceRecurringSchedule" WHERE id=NEW."scheduleId";
  IF s.id IS NULL OR NOT s.active OR NOT public.encova_finance_automation_access(s."createdById",s."grantId") OR NEW."requesterId"<>s."createdById" OR NEW."grantId"<>s."grantId" OR NEW.month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' OR NEW.month<s."startMonth" OR(s."endMonth" IS NOT NULL AND NEW.month>s."endMonth") OR NEW."postingDate"<>(NEW.month||'-01')::date+s.day-1 OR NEW."postingDate">(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Karachi')::date OR NEW.state<>'QUEUED' OR NEW.version<>1 OR NEW.attempts<>0 OR NEW.budget<>3 OR NEW."leaseId" IS NOT NULL OR NEW."sourceId" IS NOT NULL OR NEW."errorCode" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_AUTOMATION_SOURCE' USING ERRCODE='P0001';END IF;
 ELSIF TG_TABLE_NAME='FinanceRecurringAttempt' THEN
  SELECT * INTO r FROM public."FinanceRecurringRun" WHERE id=NEW."runId";
  IF r.id IS NULL OR r.state<>'RUNNING' OR NEW."leaseId" IS DISTINCT FROM r."leaseId" OR NEW.attempt<>r.attempts OR NEW.outcome<>'RUNNING' OR NEW."finishedAt" IS NOT NULL OR NEW."errorCode" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_AUTOMATION_SOURCE' USING ERRCODE='P0001';END IF;
 END IF;RETURN NEW;
END $$;
CREATE FUNCTION encova_finance_automation_ready_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE s public."FinanceRecurringSchedule"%ROWTYPE;expected_reference TEXT;valid BOOLEAN:=false;BEGIN
 IF NEW.state<>'READY' THEN RETURN NEW;END IF;
 SELECT * INTO s FROM public."FinanceRecurringSchedule" WHERE id=NEW."scheduleId";expected_reference:='REC-'||s.id::text||'-'||NEW.month;
 IF OLD.state<>'RUNNING' OR NOT s.active OR NOT public.encova_finance_automation_access(NEW."requesterId",NEW."grantId") OR NOT EXISTS(SELECT 1 FROM public."FinanceRecurringAttempt" WHERE "runId"=OLD.id AND "leaseId"=OLD."leaseId" AND attempt=OLD.attempts AND outcome='RUNNING') OR NEW."sourceId" IS NULL OR NEW."sourceType" IS DISTINCT FROM (CASE WHEN s.kind='DEPRECIATION' THEN 'ASSET_MOVEMENT' ELSE s.kind END) THEN RAISE EXCEPTION 'FINANCE_AUTOMATION_SOURCE' USING ERRCODE='P0001';END IF;
 IF s.kind='BILL' THEN
  SELECT EXISTS(SELECT 1 FROM public."FinanceBill" b JOIN public."FinanceBillLine" l ON l."billId"=b.id WHERE b.id=NEW."sourceId" AND b.state='DRAFT' AND b.kind='BILL' AND b.reference=expected_reference AND b."createdById"=NEW."requesterId" AND b."postingDate"=NEW."postingDate" AND b."billDate"=NEW."postingDate" AND b."dueDate"=NEW."postingDate"+(s.template->>'dueDays')::integer AND b."cashAccountId" IS NULL AND b."referenceReliable" AND NOT b."duplicateAcknowledged" AND b."projectId" IS NOT DISTINCT FROM(s.template->>'projectId')::uuid AND b."partyId"=(s.template->>'partyId')::uuid AND b."payableAccountId"=(s.template->>'payableAccountId')::uuid AND b.evidence=s.evidence AND b.description=s.template->>'description' AND b."totalAmount"=(s.template->>'amount')::numeric AND b."taxAmount"=0 AND l.sequence=1 AND l.quantity=1 AND l."unitRate"=(s.template->>'amount')::numeric AND l."totalAmount"=b."totalAmount" AND l.treatment='EXPENSE' AND l.description=s.template->>'description' AND l."taxCodeId" IS NULL AND l."discountAmount"=0 AND l."taxAmount"=0 AND l."costAccountId"=(s.template->>'costAccountId')::uuid AND l."projectId" IS NOT DISTINCT FROM(s.template->>'projectId')::uuid AND(SELECT count(*) FROM public."FinanceBillLine" WHERE "billId"=b.id)=1) INTO valid;
 ELSIF s.kind='JOURNAL' THEN
  SELECT EXISTS(SELECT 1 FROM public."FinanceJournalDraft" d WHERE d.id=NEW."sourceId" AND d.state='DRAFT' AND d.reference=expected_reference AND d."createdById"=NEW."requesterId" AND d."postingDate"=NEW."postingDate" AND d.evidence=s.evidence AND d.description=s.template->>'description' AND(SELECT count(*) FROM public."FinanceJournalDraftLine" WHERE "draftId"=d.id)=2 AND EXISTS(SELECT 1 FROM public."FinanceJournalDraftLine" WHERE "draftId"=d.id AND sequence=1 AND "accountId"=(s.template->>'debitAccountId')::uuid AND debit=(s.template->>'amount')::numeric AND credit=0 AND "projectId" IS NOT DISTINCT FROM(s.template->>'projectId')::uuid) AND EXISTS(SELECT 1 FROM public."FinanceJournalDraftLine" WHERE "draftId"=d.id AND sequence=2 AND "accountId"=(s.template->>'creditAccountId')::uuid AND credit=(s.template->>'amount')::numeric AND debit=0 AND "projectId" IS NOT DISTINCT FROM(s.template->>'projectId')::uuid)) INTO valid;
 ELSE
  SELECT EXISTS(SELECT 1 FROM public."FinanceAssetMovement" WHERE id=NEW."sourceId" AND kind='DEPRECIATION' AND "assetId"=(s.template->>'assetId')::uuid AND month=NEW.month AND "expenseAccountId"=(s.template->>'expenseAccountId')::uuid AND "accumulatedAccountId"=(s.template->>'accumulatedAccountId')::uuid) INTO valid;
 END IF;
 IF NOT valid THEN RAISE EXCEPTION 'FINANCE_AUTOMATION_SOURCE' USING ERRCODE='P0001';END IF;RETURN NEW;
END $$;
CREATE FUNCTION encova_finance_opening_credit_review_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE target UUID;side TEXT;valid BOOLEAN;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."FinanceSettings" s JOIN public."Person" p ON p.id=s."ownerId" JOIN public."FinanceGrant" g ON g.id=s."ownerGrantId" AND g."userId"=p.id WHERE p.id=NEW."createdById" AND p.role='SUPER_ADMIN' AND p.status='ACTIVE' AND g."revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_OWNER_REQUIRED' USING ERRCODE='P0001';END IF;
 IF NEW."customerDocumentId" IS NOT NULL AND NEW."supplierDocumentId" IS NULL THEN
  target:=NEW."customerDocumentId";side:='CUSTOMER';SELECT EXISTS(SELECT 1 FROM public."FinanceCustomerDocument" d JOIN public."FinanceOpeningLine" l ON l.id=d."creditInvoiceId" WHERE d.id=target AND d.state='DRAFT' AND d.kind='CUSTOMER_CREDIT' AND l.kind='AR') INTO valid;
 ELSIF NEW."supplierDocumentId" IS NOT NULL AND NEW."customerDocumentId" IS NULL THEN
  target:=NEW."supplierDocumentId";side:='SUPPLIER';SELECT EXISTS(SELECT 1 FROM public."FinanceSupplierDocument" d JOIN public."FinanceOpeningLine" l ON l.id=d."creditBillId" WHERE d.id=target AND d.state='DRAFT' AND d.kind='SUPPLIER_CREDIT' AND l.kind='AP') INTO valid;
 ELSE valid:=false;END IF;
 IF NOT valid OR NEW."basisHash" IS DISTINCT FROM public.encova_finance_opening_credit_basis(side,target) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."offsetAccountId" AND active AND "isPosting" AND type='EQUITY' AND "controlType"='NONE' AND NOT "isContra" AND NOT "isCashEquivalent" AND currency='PKR') THEN RAISE EXCEPTION 'FINANCE_OPENING_CREDIT_REVIEW' USING ERRCODE='P0001';END IF;RETURN NEW;
END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['FinanceRecurringSchedule','FinanceRecurringRun','FinanceRecurringAttempt'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.encova_finance_automation_insert_guard()',t||'_source_insert',t);END LOOP;END $$;
CREATE TRIGGER "FinanceRecurringRun_ready_proof" BEFORE UPDATE ON "FinanceRecurringRun" FOR EACH ROW EXECUTE FUNCTION encova_finance_automation_ready_guard();
CREATE TRIGGER "FinanceOpeningCreditReview_source" BEFORE INSERT ON "FinanceOpeningCreditReview" FOR EACH ROW EXECUTE FUNCTION encova_finance_opening_credit_review_guard();
DO $$ DECLARE f RECORD;r TEXT;BEGIN FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('encova_finance_automation_insert_guard','encova_finance_automation_ready_guard','encova_finance_opening_credit_review_guard') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);FOREACH r IN ARRAY ARRAY['encova_app','anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r);END IF;END LOOP;END LOOP;END $$;
COMMIT;
